/* 장면별 나레이션 음성 (km 목소리). 키: 영상id/장면id, t: 녹음한 대사. CrownyTools/pt-video-narration/make-voice.py 가 만든다 */
window.NARR={"start/hook": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "아직도 터미널 켜고 폴더 찾아 들어가세요? 더블클릭 한 번으로 끝내요."}, "start/intro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "파워터미널 기본편입니다. 설치하고 첫 세션을 여는 방법을 알려 드릴게요."}, "start/down": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "포미널 닷컴에서 내려받기를 누르면 압축 파일 하나가 받아집니다. 받은 파일의 압축을 풀어 주세요."}, "start/start": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "압축을 푼 폴더에서 스타트 파일을 두 번 누르세요. 필요한 것은 알아서 설치하고, 브라우저에 파워터미널이 열립니다."}, "start/add": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "오른쪽 위 세션 단추를 누르고 작업할 폴더를 고르세요. 한 번 연 폴더는 목록에 남아서 다음엔 한 번에 열립니다."}, "start/ask": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "폴더를 고르면 그 자리에서 클로드가 켜집니다. 아래 칸에 할 일을 적고 전송을 누르면, 클로드가 그 폴더에서 일을 시작해요."}, "start/outro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "설치부터 첫 요청까지, 일 분이면 끝. 파워터미널이었습니다."}, "grid/hook": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "잠깐! 창 네 개 왔다 갔다 하세요? 한 화면에서 다 보세요."}, "grid/intro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "파워터미널 기본편입니다. 여러 세션을 나란히 두고 쓰는 방법을 알려 드릴게요."}, "grid/more": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "세션을 하나 더 열 때마다 화면이 알아서 나뉩니다. 프로젝트마다 클로드가 따로 일해요."}, "grid/status": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "일하는 중인 세션은 파란 테두리, 일을 마친 세션은 초록 테두리가 됩니다. 일이 끝나면 소리로도 알려 줘요."}, "grid/sound": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "위쪽 스피커 단추를 켜 두면, 일이 끝난 세션 번호를 소리로 불러 줍니다. 다른 일을 하다가도 바로 알 수 있어요."}, "grid/model": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "세션 위 칸에서 쓸 모델을 세션마다 따로 고를 수 있어요. 클로드와 GPT도 세션마다 정합니다."}, "grid/outro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "프로젝트 네 개도 한 화면에서. 파워터미널이었습니다."}, "phone/hook": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "퇴근길에 작업 잘 되고 있나 궁금하다면? 폰으로 바로 확인하세요."}, "phone/intro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "파워터미널 기본편입니다. 폰으로 이어서 쓰는 방법을 알려 드릴게요."}, "phone/qr": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "위쪽 큐알 단추를 누르세요. 주의할 점을 읽고, 이해했습니다 큐알 보기를 누르면 됩니다."}, "phone/scan": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "폰 카메라로 큐알을 비추면 주소가 열리고, 바로 피시와 같은 화면이 나옵니다."}, "phone/same": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "폰에서도 피시와 같은 세션이 보입니다. 위쪽 이름을 눌러 세션을 오가고, 아래 칸에 바로 요청하세요."}, "phone/end": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "피시에서 파워터미널을 끄면 밖에서 들어오던 주소도 바로 끊기고, 다음에 켜면 새 주소가 생겨요."}, "phone/outro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "어디서든 내 피시 그대로. 파워터미널이었습니다."}, "input/hook": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "진행해, 다 했어? 매번 치세요? 단추 한 번이면 돼요."}, "input/intro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "파워터미널 요청편입니다. 요청창을 빠르게 쓰는 방법을 알려 드릴게요."}, "input/chips": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "입력칸 위 단추를 누르면 그 말이 바로 보내집니다. 더하기를 눌러 내가 자주 쓰는 말을 더할 수 있어요."}, "input/img": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "캡처한 화면을 입력칸에 붙여 넣으면 그림으로 첨부됩니다. 클로드가 그 그림을 보고 일해요."}, "input/mic": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "마이크 단추를 누르고 말하면 글로 바뀌어 입력칸에 들어갑니다. 확인하고 전송을 누르세요."}, "input/q": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "질문으로 시작해서 보내면, 답변이 그 폴더의 메모장에 따로 기록됩니다. 나중에 다시 찾아보기 좋아요."}, "input/hist": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "요청내역을 누르면 지금까지 보낸 요청이 모두 나옵니다. 컨트롤과 위 화살표로 이전 글을 다시 불러올 수도 있어요."}, "input/outro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "요청은 짧게, 일은 AI가. 파워터미널이었습니다."}, "book/hook": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "휴, 어디까지 읽었는지 또 잃어버렸나요? 책처럼 넘겨 보세요."}, "book/intro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "파워터미널 요청편입니다. 긴 대화를 책처럼 읽는 노트모드를 알려 드릴게요."}, "book/open": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "위쪽 책 단추를 누르면 마지막으로 쓴 세션의 대화가 책으로 열립니다."}, "book/flip": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "요청과 답변이 쪽으로 나뉘어 있어요. 화살표나 휠로 넘기고, 보던 쪽은 다음에 열어도 그대로입니다."}, "book/ask": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "마지막 쪽 아래 칸에 쓰면 그 세션에 바로 요청이 갑니다. 그림도 붙여 넣을 수 있어요."}, "book/tools": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "오른쪽에서 대화를 검색하고, 글자 크기를 바꾸고, 원고 파일로 내보낼 수도 있어요."}, "book/outro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "긴 대화도 한 쪽씩 편하게. 파워터미널이었습니다."}, "auto/hook": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "사용량 한도 풀리길 기다리며 깨어 있나요? 자동 실행에 맡기세요."}, "auto/intro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "파워터미널 요청편입니다. 정한 때에 요청을 자동으로 보내는 방법을 알려 드릴게요."}, "auto/open": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "위쪽 자동 실행을 누르면 예약 화면이 새 창으로 열립니다."}, "auto/when": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "요청을 보낼 세션을 고르고, 언제 보낼지 고르세요. 지정 시각에 한 번, 일정 간격으로 반복, 또는 사용량이 초기화되면 이어하기가 있어요."}, "auto/text": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "보낼 요청을 적고 최대 몇 번까지 보낼지 정한 뒤 예약 저장을 누르세요."}, "auto/run": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "때가 되면 세션이 일하는 중인지 보고, 쉬고 있을 때 요청을 보냅니다. 피시와 파워터미널만 켜져 있으면 돼요."}, "auto/outro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "자는 동안에도 일은 계속. 파워터미널이었습니다."}, "browser/hook": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "페이지 열어서 확인해 주세요? 이제 AI가 직접 열어 보게 하세요."}, "browser/intro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "파워터미널 AI 도구편입니다. AI가 진짜 크롬으로 일하게 하는 방법을 알려 드릴게요."}, "browser/globe": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "세션 위 지구 단추를 누르면, 이 세션의 AI가 쓸 브라우저를 고르는 창이 나옵니다."}, "browser/mode": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "일반창은 로그인이 남아서 다음에도 이어서 쓰고, 시크릿창은 끌 때마다 깨끗하게 지워집니다. 여기서는 일반창을 고를게요."}, "browser/work": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "이제 요청하면 AI가 크롬을 열어 페이지를 보고, 누르고, 적고, 결과를 확인합니다."}, "browser/tab": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "여러 세션이 같은 창을 써도, 탭 제목에 세션 이름이 붙어서 누가 연 탭인지 바로 보여요."}, "browser/outro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "확인은 AI가, 나는 결과만. 파워터미널이었습니다."}, "vault/hook": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "로그인 화면에서 멈춘 AI에게, 채팅창으로 비밀번호 적어 주시려고요? 보관함에 넣어 두세요."}, "vault/intro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "파워터미널 AI 도구편입니다. 비밀번호를 AI에게 보여 주지 않고 로그인시키는 방법을 알려 드릴게요."}, "vault/open": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "지구 단추를 누르고, 로그인 보관함을 여세요."}, "vault/add": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "이름과 사이트 주소, 아이디, 비밀번호를 적고 저장하세요. 비밀번호는 이 컴퓨터에 암호로 바뀌어 저장되고, 다시 보여 주지 않습니다."}, "vault/chrome": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "크롬에 저장해 둔 비밀번호도 가져올 수 있어요. 크롬에서 내보낸 파일을 고르면, 모두 한 번에 넣거나 하나씩 골라 넣을 수 있습니다."}, "vault/ai": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "AI는 로그인 화면을 만나면 이름만 부르고, 파워터미널이 저장된 주소인지 확인한 뒤 직접 입력합니다. AI는 비밀번호를 끝까지 보지 못해요."}, "vault/outro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "비밀번호는 안전하게, 로그인은 알아서. 파워터미널이었습니다."}, "helper/hook": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "AI가 다 만들어 줬는데, 이제 나는 뭘 누르면 되죠? 도우미가 짚어 드려요."}, "helper/intro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "파워터미널 AI 도구편입니다. 할 일을 화면에서 하나씩 짚어 주는 도우미를 알려 드릴게요."}, "helper/install": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "위쪽 도우미 설치를 한 번 누르세요. 화면 위에 말풍선을 띄우는 작은 앱이 이 컴퓨터에 설치됩니다."}, "helper/ask": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "도우미 단추를 누르고 알려줘를 누르면, 그 세션에 방금 요청한 일을 내가 직접 해 보는 순서로 안내해 줍니다."}, "helper/point": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "말풍선이 누를 곳을 짚어 주고, 그대로 하면 저절로 체크된 뒤 다음 할 일로 넘어갑니다."}, "helper/any": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "평소 쓰는 크롬이나 다른 프로그램 위에서도 짚어 주고, 주소로 접속한 다른 컴퓨터에서도 도우미를 설치해 쓸 수 있어요."}, "helper/outro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "다음에 뭘 할지, 도우미가 알려줘요. 파워터미널이었습니다."}, "newproj/hook": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "새 아이디어가 떠올랐을 때, 폴더 만들고 깃 켜고 깃허브까지 하나씩 하세요? 한 번에 끝내요."}, "newproj/intro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "파워터미널 기본편입니다. 새 프로젝트를 한 번에 만드는 방법을 알려 드릴게요."}, "newproj/tab": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "오른쪽 위 세션 단추를 누르고, 새 프로젝트 탭을 고르세요."}, "newproj/name": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "프로젝트 이름을 적고 만들고 시작을 누르면, 폴더를 만들고 깃을 켜고 깃허브에 비공개 저장소까지 연결합니다. 처음 한 번은 깃허브 로그인이 필요해요."}, "newproj/ready": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "다 되면 그 폴더에서 세션이 바로 열립니다. 아래 줄에 깃허브 저장소 이름이 보이면 연결된 거예요."}, "newproj/outro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "아이디어에서 첫 요청까지 한 번에. 파워터미널이었습니다."}, "memo/hook": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "어제 물어본 그 답, 터미널을 한참 거슬러 올라가 찾나요? 메모장에 다 남아요."}, "memo/intro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "파워터미널 요청편입니다. 세션마다 있는 메모장을 알려 드릴게요."}, "memo/open": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "세션 이름 쪽에 마우스를 올리면 메모 단추가 나옵니다. 누르면 그 폴더의 메모장이 열려요."}, "memo/cols": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "왼쪽은 내 메모, 가운데는 질문으로 물어본 답변, 오른쪽은 지금까지 보낸 요청이 자동으로 모입니다."}, "memo/send": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "메모를 적어 두었다가 전송을 누르면 그대로 세션에 요청이 갑니다. 일이 끝나면 완료된 항목으로 옮겨져요."}, "memo/xls": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "엑셀 단추를 누르면 모든 세션의 메모와 요청 내역이 서식 있는 엑셀 파일 하나로 저장됩니다."}, "memo/outro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "물어본 답도 다시 찾기 쉽게. 파워터미널이었습니다."}, "code/hook": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "AI가 고친 파일 확인하려고 다른 편집기를 또 켜세요? 바로 옆에서 보고 고쳐요."}, "code/intro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "파워터미널 도구편입니다. 세션 옆에서 파일을 보고 고치는 코드 편집기를 알려 드릴게요."}, "code/open": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "위쪽 코드 단추를 누르면, 마지막으로 쓴 세션이 코드 편집 화면으로 바뀝니다."}, "code/layout": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "왼쪽에 세션과 터미널, 가운데에 코드, 오른쪽에 파일 목록이 있어요. 파일을 누르면 바로 열립니다."}, "code/edit": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "고친 뒤 저장을 누르거나 컨트롤 에스를 누르면 저장됩니다. 옆의 클로드에게 그대로 이어서 요청할 수도 있어요."}, "code/prev": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "미리보기를 누르면 만들고 있는 페이지가 그 자리에서 열려서, 고친 결과를 바로 볼 수 있어요."}, "code/outro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "보고, 고치고, 바로 확인. 파워터미널이었습니다."}, "git/hook": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "다 만들었으면 이제 깃 애드, 커밋, 푸시, 풀 리퀘스트? 우클릭 한 번이면 돼요."}, "git/intro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "파워터미널 도구편입니다. 작업한 폴더를 깃허브에 올리는 방법을 알려 드릴게요."}, "git/bar": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "깃 폴더면 세션 아래에 브랜치와 바뀐 파일 수가 보여요. 이 줄을 오른쪽 단추로 누르세요."}, "git/up": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "깃허브에 올리기를 누르면 올라갈 파일과 피알 제목이 나옵니다. 확인하고 올리기를 누르면 커밋부터 피알까지 알아서 해요."}, "git/merge": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "합칠 때도 같은 줄을 오른쪽 단추로 눌러 메인에 합치기를 고르면 됩니다. 이 폴더도 메인으로 돌아와 깃허브와 똑같이 맞춰져요."}, "git/secret": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "비밀번호 같은 비밀 파일이 올라갈 목록에 있으면, 올리기 전에 멈추고 알려 줍니다."}, "git/outro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "커밋부터 피알까지 우클릭 한 번. 파워터미널이었습니다."}, "mind/hook": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "어휴, 어디서부터 해야 할지 모르겠다면? 가지로 펼쳐 보세요."}, "mind/intro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "파워터미널 도구편입니다. 생각을 정리하는 마인드맵을 알려 드릴게요."}, "mind/open": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "위쪽 마인드맵 단추를 누르면 내 지도가 열립니다."}, "mind/branch": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "가지에 마우스를 올려 더하기를 누르거나, 더하기 키를 누르면 새 가지가 생겨요. 이름은 바로 적으면 됩니다."}, "mind/link": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "가지는 끌어서 옮기고, 연결 단추로 가지 사이에 화살표를 그을 수 있어요."}, "mind/save": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "왼쪽에는 할 일 목록이 있고, 이미지 저장을 누르면 지도를 그림 파일로 내려받습니다."}, "mind/outro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "복잡한 생각도 한 장으로. 파워터미널이었습니다."}, "m-start/hook": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "소파에 누워서, 피시 앞에 다시 앉지 않아도 폰에서 다 돼요."}, "m-start/intro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "파워터미널 모바일편입니다. 폰에서 세션을 오가고 요청하는 방법을 알려 드릴게요."}, "m-start/open": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "피시의 큐알을 찍어 연 주소가 바로 폰 화면입니다. 홈 화면에 추가해 두면 앱처럼 열려요."}, "m-start/switch": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "위쪽 세션 이름을 누르면 그 세션으로 바로 넘어갑니다."}, "m-start/chips": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "자주 쓰는 말 단추를 누르면 바로 보내지고, 아래 칸에 적어서 전송해도 됩니다."}, "m-start/zoom": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "네모 단추를 누르면 그 세션만 화면 가득 크게 보여요. 위쪽 닫기를 누르면 돌아옵니다."}, "m-start/outro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "손안에서 내 피시 그대로. 파워터미널이었습니다."}, "m-input/hook": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "설명하기 어려운 화면이라면? 사진으로 보내세요."}, "m-input/intro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "파워터미널 모바일편입니다. 폰에서 사진과 말로 요청하는 방법을 알려 드릴게요."}, "m-input/clip": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "클립 단추를 누르고 사진을 고르면, 입력칸에 그림으로 붙습니다."}, "m-input/mic": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "마이크 단추를 누르고 말하면 글로 바뀌어 들어갑니다. 마이크는 밖에서 쓰는 큐알 주소에서 쓸 수 있어요."}, "m-input/send": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "적힌 글과 사진을 확인하고 전송을 누르면, 피시의 클로드가 그 사진을 보고 일합니다."}, "m-input/outro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "보여 주고 말하면 AI가 알아들어요. 파워터미널이었습니다."}, "m-book/hook": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "긴 답변, 폰으로 보기 힘들었다면? 책처럼 넘겨 읽어요."}, "m-book/intro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "파워터미널 모바일편입니다. 폰에서 노트모드로 읽는 방법을 알려 드릴게요."}, "m-book/swipe": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "손가락으로 밀면 종이처럼 넘어가고, 빠르게 쓸면 여러 장을 한 번에 넘깁니다. 가장자리를 톡 눌러도 한 장씩 넘어가요."}, "m-book/listen": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "두 손가락으로 글을 누르면 듣기 단추가 나옵니다. 누르면 그 자리부터 소리로 읽어 줘요."}, "m-book/search": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "페이지를 아래로 쓸어내리면 검색 칸이 내려옵니다. 찾은 곳을 누르면 그 쪽으로 가요."}, "m-book/ask": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "맨 아래 칸에 적어 보내면 그 세션에 바로 요청이 갑니다."}, "m-book/outro": {"d": "data:audio/mpeg;base64,", "n": "km 목소리", "t": "어디서든 한 쪽씩 편하게. 파워터미널이었습니다."}};
